        /// <summary>Settings → the app card: version, mode (portable), data location, rights.</summary>
        private void UpdateSettingsAppCard()
        {
            try
            {
                if (TxtSettingsAppVersion == null || TxtSettingsAppInfo == null) return;
                var v = System.Reflection.Assembly.GetExecutingAssembly().GetName().Version;
                TxtSettingsAppVersion.Text = $"SMD Win · {SMDWin.Services.AppVersionInfo.Short}";
                bool admin = SMDWin.Services.PermissionHelper.IsRunningAsAdmin();
                TxtSettingsAppInfo.Text =
                    "Portable · settings and reports saved in " + SMDWin.Services.AppPaths.DataDirectory +
                    (admin ? " · running as Administrator" : " · running as standard user (some sensors need Administrator)");
                if (TxtDataFolderPath != null) TxtDataFolderPath.ToolTip = SMDWin.Services.AppPaths.DataDirectory;
            }
            catch (Exception ex) { SMDWin.Services.AppLogger.Warning(ex, "UpdateSettingsAppCard"); }
        }

        private async void UnknownHardwareReport_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var r = await Task.Run(() => SMDWin.Services.UnknownHardwareReport.Create());
                if (r.Path == null)
                    AppDialog.Show(string.Format(LanguageService.S("Msg", "HwReportAllKnownFmt"), r.TotalChecked), LanguageService.S("Msg", "HwReportTitle"), AppDialog.Kind.Success);
                else
                {
                    AppDialog.Show((r.UnknownCount > 0
                        ? $"{r.UnknownCount} of {r.TotalChecked} components are not in the hardware database yet."
                        : $"All {r.TotalChecked} components were recognized; RAM part numbers were saved.") +
                        $"\n\nSaved to:\n{r.Path}", "Unknown hardware report", AppDialog.Kind.Info);
                    System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("explorer.exe", $"/select,\"{r.Path}\"") { UseShellExecute = true });
                }
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "UnknownHardwareReport_Click");
                AppDialog.Show(string.Format(LanguageService.S("Msg", "HwReportFailFmt"), ex.Message), LanguageService.S("Msg", "HwReportTitle"), AppDialog.Kind.Warning);
            }
        }

        internal void OpenDataFolder_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("explorer.exe",
                    "\"" + SMDWin.Services.AppPaths.DataDirectory + "\"") { UseShellExecute = true });
            }
            catch (Exception ex) { SMDWin.Services.AppLogger.Warning(ex, "OpenDataFolder_Click"); }
        }

        private void LoadSettingsIntoUI()
        {
            UpdateSettingsAppCard();
            // Temporarily unsubscribe the handlers so Settings_Changed does not fire when values are set programmatically
            // (it could overwrite UseMica with false)
            ChkMinimize.Checked   -= Settings_Changed; ChkMinimize.Unchecked   -= Settings_Changed;
            if (ChkEnableNotifications != null) { ChkEnableNotifications.Checked -= Settings_Changed; ChkEnableNotifications.Unchecked -= Settings_Changed; }
            if (ChkAnimations != null) { ChkAnimations.Checked -= Settings_Changed; ChkAnimations.Unchecked -= Settings_Changed; }
            if (ChkSounds != null) { ChkSounds.Checked -= Settings_Changed; ChkSounds.Unchecked -= Settings_Changed; }
            if (ChkAuroraAlert != null) { ChkAuroraAlert.Checked -= Settings_Changed; ChkAuroraAlert.Unchecked -= Settings_Changed; }
            if (ChkUseLhm != null) { ChkUseLhm.Checked -= ChkUseLhm_Changed; ChkUseLhm.Unchecked -= ChkUseLhm_Changed; }
            SliderRefresh.ValueChanged   -= SliderRefresh_ValueChanged;
            SliderEventDays.ValueChanged -= SliderEventDays_ValueChanged;

            var s = SettingsService.Current;
            LoadBehaviorPrefsIntoUI();
            SliderRefresh.Value    = s.RefreshInterval;
            SliderEventDays.Value  = s.EventDaysBack;
            // Temperature: GPU button highlight
            if (TxtTempGpuVal != null) TxtTempGpuVal.Text = $"{(int)s.TempWarnGpu}°C";
            UpdateTempButtonStyles((int)s.TempWarnGpu, isCpu: false);
            ChkMinimize.IsChecked  = s.CloseToTray;
            if (ChkStartWithWindows != null) ChkStartWithWindows.IsChecked = s.StartWithWindows;
            if (ChkEnableNotifications != null) ChkEnableNotifications.IsChecked = s.EnableNotifications;
            if (ChkAutoSnapshotStress != null) ChkAutoSnapshotStress.IsChecked = s.AutoSnapshotOnStress;
            if (ChkExportSensorsReg != null) ChkExportSensorsReg.IsChecked = s.ExportSensorsToRegistry;
            if (ChkAnimations != null) ChkAnimations.IsChecked = s.EnableAnimations;
            if (ChkSounds != null) ChkSounds.IsChecked = s.PlaySounds;
            if (ChkAuroraAlert != null) ChkAuroraAlert.IsChecked = s.AuroraAlertTint;
            // Mica — hide checkbox entirely on Win10 and earlier

            if (ChkAutoTheme != null) ChkAutoTheme.IsChecked = s.AutoTheme || s.ThemeName == "Auto";
            ShowCurrentThemeLabel(s.ThemeName, s.AutoTheme || s.ThemeName == "Auto");

            // Process refresh display + highlight
            if (TxtProcRefreshVal != null) TxtProcRefreshVal.Text = $"{s.ProcessRefreshSec}s";
            if (TxtTempRefreshVal != null) TxtTempRefreshVal.Text = $"{s.RefreshInterval}s";
            // Highlight the currently selected chip buttons (same style as temp thresholds)
            if (ProcRefreshChipPanel != null)
                UpdateChipSelection(ProcRefreshChipPanel, s.ProcessRefreshSec.ToString());

            // Chart settings
            UpdateChartWindowButtonStyles(s.ChartWindowSeconds);
            if (TempRefreshChipPanel != null)
            {
                string tempTag = s.RefreshInterval <= 0.5 ? "0.5"
                               : s.RefreshInterval <= 1   ? "1"
                               : s.RefreshInterval <= 2   ? "2"
                               : s.RefreshInterval <= 3   ? "3"
                               : s.RefreshInterval <= 5   ? "5" : "10";
                // RadioButton chips — set IsChecked
                foreach (var child in TempRefreshChipPanel.Children.OfType<System.Windows.Controls.RadioButton>())
                    child.IsChecked = (child.Tag?.ToString() == tempTag);
            }

            // Network refresh chip
            if (NetRefreshChip1 != null)
            {
                string netTag = s.NetworkRefreshSec <= 1 ? "1"
                              : s.NetworkRefreshSec <= 2 ? "2"
                              : s.NetworkRefreshSec <= 5 ? "5" : "10";
                foreach (var rb in new[] { NetRefreshChip1, NetRefreshChip2, NetRefreshChip5, NetRefreshChip10 })
                    if (rb != null) rb.IsChecked = (rb.Tag?.ToString() == netTag);
            }

            // Battery refresh chip
            if (BatRefreshChip5 != null)
            {
                string batTag = s.BatteryRefreshSec <= 5  ? "5"
                              : s.BatteryRefreshSec <= 10 ? "10"
                              : s.BatteryRefreshSec <= 30 ? "30" : "60";
                foreach (var rb in new[] { BatRefreshChip5, BatRefreshChip10, BatRefreshChip30, BatRefreshChip60 })
                    if (rb != null) rb.IsChecked = (rb.Tag?.ToString() == batTag);
            }

            _evtFrom = DateTime.Today.AddDays(-s.EventDaysBack);
            _evtTo = DateTime.Today.AddDays(1);

            // Driver search site
            if (RbDriverSearchGoogle != null)
                RbDriverSearchGoogle.IsChecked = s.DriverSearchSite == "google";
            if (RbDriverSearchDrp != null)
                RbDriverSearchDrp.IsChecked = s.DriverSearchSite != "google";

            // LHM sensor toggle
            if (ChkUseLhm != null) ChkUseLhm.IsChecked = s.UseLhm;
            UpdateSensorBackendLabel();
            RefreshPawnIoStatus();   // PAWNIO: shows the driver state when Settings opens

            // Compact Widget — mode radio + metric checkboxes
            bool isCompact = s.WidgetMode == "Compact";
            if (RbWidgetCompact != null) RbWidgetCompact.IsChecked = isCompact;
            if (RbWidgetNormal  != null) RbWidgetNormal.IsChecked  = !isCompact;
            LoadCompactMetricCheckboxes(s.WidgetCompactMetrics ?? "CPU,GPU,RAM,NetUp,NetDown,Battery");
            UpdateWidgetStyleButtons();
            if (ChkWidgetAlertOnly != null) ChkWidgetAlertOnly.IsChecked = s.WidgetAlertOnlyMode;
            if (ChkWidgetEnabled != null)
                ChkWidgetEnabled.IsChecked = _compactWidget != null && _compactWidget.IsVisible;
            if (ChkTraySensors != null) ChkTraySensors.IsChecked = s.TraySensorsEnabled;
            UpdateWidgetTrayPanels();

            // Highlight active theme button
            HighlightActiveThemeButton(s.ThemeName, s.AutoTheme);
            HighlightActiveAccentButton(s.AccentName ?? "Blue");

            ChkMinimize.Checked   += Settings_Changed; ChkMinimize.Unchecked   += Settings_Changed;
            if (ChkEnableNotifications != null) { ChkEnableNotifications.Checked += Settings_Changed; ChkEnableNotifications.Unchecked += Settings_Changed; }
            if (ChkAnimations != null) { ChkAnimations.Checked += Settings_Changed; ChkAnimations.Unchecked += Settings_Changed; }
            if (ChkSounds != null) { ChkSounds.Checked += Settings_Changed; ChkSounds.Unchecked += Settings_Changed; }
            if (ChkAuroraAlert != null) { ChkAuroraAlert.Checked += Settings_Changed; ChkAuroraAlert.Unchecked += Settings_Changed; }
            if (ChkUseLhm != null) { ChkUseLhm.Checked += ChkUseLhm_Changed; ChkUseLhm.Unchecked += ChkUseLhm_Changed; }
            SliderRefresh.ValueChanged   += SliderRefresh_ValueChanged;
            SliderEventDays.ValueChanged += SliderEventDays_ValueChanged;
            LoadSettingsTabsIntoUI();
        }

        internal void SliderRefresh_ValueChanged(object s, RoutedPropertyChangedEventArgs<double> e)
        {
            // Snap to preset values: 0.2 / 0.5 / 1 / 2 / 5
            double raw = e.NewValue;
            double v = raw < 0.35 ? 0.2
                     : raw < 0.75 ? 0.5
                     : raw < 1.5  ? 1.0
                     : raw < 3.5  ? 2.0
                     : 5.0;
            if (TxtRefreshVal != null) TxtRefreshVal.Text = v < 1 ? $"{v:F1}s" : $"{(int)v}s";
            if (SettingsService.Current.RefreshInterval == v) return;
            SettingsService.Current.RefreshInterval = v;
            _tempTimer.Interval = TimeSpan.FromSeconds(v);
        }


        internal void SliderEventDays_ValueChanged(object s, RoutedPropertyChangedEventArgs<double> e)
        {
            if (TxtEventDaysVal == null) return;
            int v = (int)e.NewValue;
            TxtEventDaysVal.Text = $"{v}z";
            SettingsService.Current.EventDaysBack = v;
        }




