        // the isCpu parameter stays for signature compatibility (the calls use isCpu: false); the method only updates the GPU button set.
        private void UpdateTempButtonStyles(int selected, bool isCpu)
        {
            if (isCpu) return; // the CPU buttons do not exist
            // Now using RadioButton — just set IsChecked on the matching one
            System.Windows.Controls.RadioButton[][] sets =
                new[] { new[] { BtnGpuTemp80, BtnGpuTemp85, BtnGpuTemp90, BtnGpuTemp95, BtnGpuTemp100 } };

            foreach (var set in sets)
                foreach (var b in set)
                    if (b != null)
                    {
                        int val = int.Parse(b.Tag?.ToString() ?? "0");
                        b.IsChecked = (val == selected);
                    }
        }

        internal void ChartTimeRange_Click(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            if (sender is not Border btn) return;
            int seconds = btn.Tag?.ToString() switch
            {
"60"=> 60,
"300"=> 300,
"900"=> 900,
"3600" => 3600,
                _      => 60,
            };
            if (seconds == _stressChartRangeSeconds) return;
            _stressChartRangeSeconds = seconds;
            _slotDrawn.Clear();

            // Reset min/max tracking for the new window
            _cpuMin = null; _cpuMax = null; _gpuMin = null; _gpuMax = null;
            _diskTempMinMax.Clear();
            _cpuFreqMin = float.MaxValue; _cpuFreqMax = 0f; _cpuFreqSum = 0f; _cpuFreqCount = 0;
            _cpuFreqMin = float.MaxValue; _cpuFreqMax = float.MinValue;
            _gpuTempMin = float.MaxValue; _gpuTempMax = 0f; _gpuTempSum = 0f; _gpuTempCnt = 0;
            _cpuLoadMin = float.MaxValue; _cpuLoadMax = 0f; _cpuLoadSum = 0f; _cpuLoadCnt = 0;
            _gpuLoadMin = float.MaxValue; _gpuLoadMax = 0f; _gpuLoadSum = 0f; _gpuLoadCnt = 0; _gpuPwMin = float.MaxValue; _gpuPwMax = 0f;
            _ramLoadMin = float.MaxValue; _ramLoadMax = 0f; _ramLoadSum = 0f; _ramLoadCnt = 0;
            _cpuPowerMin = float.MaxValue; _cpuPowerMax = float.MinValue;
            _gpuFreqMin = float.MaxValue; _gpuFreqMax = float.MinValue;
            _gpuPowerMin = float.MaxValue; _gpuPowerMax = float.MinValue;
            _gpuVramMin = null; _gpuVramMax = null;
            _cpuVCoreMin = float.MaxValue; _cpuVCoreMax = float.MinValue; _cpuVCoreSum = 0; _cpuVCoreCnt = 0;
            _gpuMemFreqMin = float.MaxValue; _gpuMemFreqMax = float.MinValue;

            // Recalculate min/max from the existing history window
            int count = Math.Min(_chartIdx, StressChartPoints);
            int start = _chartIdx >= ChartMaxPoints ? _chartIdx % ChartMaxPoints : 0;
            for (int i = 0; i < count; i++)
            {
                int idx = (start + i) % ChartMaxPoints;
                float cv = _chartCpu[idx], gv = _chartGpu[idx];
                if (!float.IsNaN(cv) && cv > 0) { _cpuMin = _cpuMin.HasValue ? Math.Min(_cpuMin.Value, cv) : cv; _cpuMax = _cpuMax.HasValue ? Math.Max(_cpuMax.Value, cv) : cv; }
                if (!float.IsNaN(gv) && gv > 0) { _gpuMin = _gpuMin.HasValue ? Math.Min(_gpuMin.Value, gv) : gv; _gpuMax = _gpuMax.HasValue ? Math.Max(_gpuMax.Value, gv) : gv; }
            }

            // Reset dirty flags so all charts redraw with new time window
            _drawnIdxTempChart = _drawnIdxSingleCpu = _drawnIdxSingleGpu =
            _drawnIdxCpuFreq = _drawnIdxCpuUsage = _drawnIdxGpuLoad = -1;

            // Force immediate redraw with current data
            try { DrawTempChart(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            try { DrawSingleTempChart((FindName("CpuTempCanvas") as System.Windows.Controls.Canvas) ?? CpuTempChart, _chartCpu, (TryFindResource("ChartBlueColor") as WpfColor?) ?? WpfColor.FromRgb(59, 130, 246), 20f, 100f, "°", "F0", SettingsService.Current.TempWarnCpu); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            try { DrawSingleTempChart((FindName("GpuTempCanvas") as System.Windows.Controls.Canvas) ?? GpuTempChart, _chartGpu, (TryFindResource("ChartBlueColor") as WpfColor?) ?? WpfColor.FromRgb(59, 130, 246), 20f, 100f, "°", "F0", SettingsService.Current.TempWarnGpu); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            try { DrawSingleTempChart((FindName("CpuFreqCanvas") as System.Windows.Controls.Canvas) ?? CpuFreqChart, _chartCpuFreq, (TryFindResource("ChartBlueColor") as WpfColor?) ?? WpfColor.FromRgb(59, 130, 246), 0f, 0f, "MHz", "F0"); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            try { DrawSingleTempChart((FindName("CpuUsageCanvas") as System.Windows.Controls.Canvas) ?? CpuUsageChart, _chartCpuUsage, (TryFindResource("ChartGreenBrush") as SolidColorBrush)?.Color ?? WpfColor.FromRgb(34, 197, 94), 0f, 100f, "%", "F0"); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            try { DrawCpuFreqChart(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            try { DrawCpuUsageChart(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            try { DrawGpuLoadChart(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
            _dashSizeChanged = true;
            // the card charts and "My charts" are redrawn now, not on the next sensor read
            RedrawStressChartsNow();
            if (_stressChartsMode) RefreshAllSlots();

            var res = System.Windows.Application.Current.Resources;
            foreach (var b in new[] { BtnChartRange1m, BtnChartRange5m, BtnChartRange15m, BtnChartRange1h })
            {
                if (b == null) continue;
                bool active = b == btn;
                ApplySegmentLook(b, active);
            }
            UpdateStressRangeButton();
        }

        internal void ChartWindowBtn_Click(object sender, System.Windows.RoutedEventArgs e)
        {
