            SettingsService.Current.ChartWindowSeconds = secs;
            _chartTimeRangeSeconds = secs;
            SettingsService.Save();
            // Resize queues to new window
            EnsureQueues(secs);
            UpdateChartWindowButtonStyles(secs);
            _slotDrawn.Clear();
            _renderDirty = true;
        }


