        private void UpdateChartWindowButtonStyles(int activeSecs)
        {
            var btns = new[] {
                (BtnChartWindow60,   60),
                (BtnChartWindow300,  300),
                (BtnChartWindow900,  900),
                (BtnChartWindow3600, 3600)
            };
            foreach (var (btn, secs) in btns)
            {
                if (btn == null) continue;
                btn.IsChecked = secs == activeSecs;
            }
        }

        internal void Settings_Changed(object s, RoutedEventArgs e)
        {
            // Guard: don't fire during XAML initialization before window is fully loaded
            if (!IsLoaded) return;

            if (ChkMinimize != null) SettingsService.Current.CloseToTray = ChkMinimize.IsChecked == true;

            SettingsService.Current.EnableNotifications = ChkEnableNotifications?.IsChecked != false;
            SettingsService.Current.AutoSnapshotOnStress = ChkAutoSnapshotStress?.IsChecked != false;
            if (ChkExportSensorsReg != null) SettingsService.Current.ExportSensorsToRegistry = ChkExportSensorsReg.IsChecked == true;
            if (ChkAnimations != null) SettingsService.Current.EnableAnimations = ChkAnimations.IsChecked == true;
            if (ChkSounds != null) SettingsService.Current.PlaySounds = ChkSounds.IsChecked == true;
            if (ChkAuroraAlert != null)
            {
                bool tint = ChkAuroraAlert.IsChecked == true;
                bool changed = SettingsService.Current.AuroraAlertTint != tint;
                SettingsService.Current.AuroraAlertTint = tint;
                if (changed) UpdateAuroraAlert();
            }

            // ColorfulIcons is no longer in the UI — keep the last saved value
            // Start with Windows — add/remove the registry Run key
            bool startWithWin = ChkStartWithWindows?.IsChecked == true;
            if (SettingsService.Current.StartWithWindows != startWithWin)
            {
                SettingsService.Current.StartWithWindows = startWithWin;
                SetStartWithWindows(startWithWin);
            }
            try { SettingsService.Save(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        private static bool IsStartWithWindowsEnabled()
        {
            const string keyPath = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Run";
            const string appName = "SMDWin";
            try
            {
                using var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(keyPath);
                return key?.GetValue(appName) != null;
            }
            catch { return false; }
        }

        private static void SetStartWithWindows(bool enable)
        {
            const string keyPath = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Run";
            const string appName = "SMDWin";
            try
            {
                using var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(keyPath, writable: true);
                if (key == null) return;
                if (enable)
                {
                    string? exePath = System.Diagnostics.Process.GetCurrentProcess().MainModule?.FileName;
                    if (!string.IsNullOrEmpty(exePath))
                        key.SetValue(appName, $"\"{exePath}\"");
                }
                else
                {
                    key.DeleteValue(appName, throwOnMissingValue: false);
                }
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.Settings_Changed"); }
        }

        private int _stressDurationMinutes = 0;
        private DateTime? _stressAutoStopAtUtcField = null;
        private System.Windows.Threading.DispatcherTimer? _stressAutoStopTimer;

        /// <summary>
        /// The moment the stress tests stop automatically ("Stop after"). Setting the deadline starts its own 1 s timer,
        /// independent of the rest of the UI: a check only from the temperature tick could be skipped if something earlier
        /// threw, or if the tick was stopped/slowed down (minimized window, monitoring paused).
        /// </summary>
        private DateTime? _stressAutoStopAtUtc
        {
            get => _stressAutoStopAtUtcField;
            set
            {
                _stressAutoStopAtUtcField = value;
                if (value.HasValue)
                {
                    if (_stressAutoStopTimer == null)
                    {
                        _stressAutoStopTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(1) };
                        _stressAutoStopTimer.Tick += (_, _) =>
                        {
                            try { CheckStressAutoStop(); }
                            catch (Exception ex) { AppLogger.Warning(ex, "CheckStressAutoStop"); }
                        };
                    }
                    _stressAutoStopTimer.Start();
                }
                else _stressAutoStopTimer?.Stop();
            }
        }

        /// <summary>The "Stop after: 3m/10m/30m/60m/∞" segments — the same visual pattern as ChartTimeRange_Click (Border, not
        /// Button — MouseLeftButtonUp), but nothing chart-related: it only remembers the choice for the next test start.</summary>
        internal void StressDuration_Click(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            if (sender is not Border btn) return;
            int minutes = int.TryParse(btn.Tag?.ToString(), out int m) ? m : 0;
            _stressDurationMinutes = minutes;

            var res = System.Windows.Application.Current.Resources;
            foreach (var b in new[] { BtnStressDur3m, BtnStressDur10m, BtnStressDur30m, BtnStressDur60m, BtnStressDurInf })
            {
                if (b == null) continue;
                bool active = b == btn;
                ApplySegmentLook(b, active);
            }

            // The duration is measured from the test START, not from the moment of the choice — test started, then "3m" at minute 1
            // → stops at 3:00 from the start. If the time has already passed (e.g. "3m" chosen at minute 5), it stops immediately.
            bool anyStressRunning = _cpuStress.Running || _gpuStress.IsRunning || _psuStress.IsRunning;
            if (anyStressRunning)
            {
                var starts = new List<DateTime>();
                if (_cpuStress.Running && (_cpuStress.StartedUtc ?? _cpuStressStartUtc) is DateTime c0) starts.Add(c0);
                if (_gpuStress.IsRunning && (_gpuStress.StartedUtc ?? _gpuStressStartUtc) is DateTime g0) starts.Add(g0);
                if (_psuStress.IsRunning && _psuStress.StartedUtc is DateTime p0) starts.Add(p0);
                DateTime startUtc = starts.Count > 0 ? starts.Min() : DateTime.UtcNow;
                _stressAutoStopAtUtc = minutes > 0 ? startUtc.AddMinutes(minutes) : (DateTime?)null;
                if (minutes > 0) CheckStressAutoStop();   // already exceeded → stop now
            }
            UpdateStressPlanUi();   // the sentence and the time on the button include the duration
        }

        /// <summary>Called when any stress test starts (CPU/GPU/Max Load) — sets the auto-stop moment after the currently
        /// chosen duration, or null for "∞".</summary>
        private void ApplyStressAutoStopIfNeeded()
        {
            _stressAutoStopAtUtc = _stressDurationMinutes > 0
                ? DateTime.UtcNow.AddMinutes(_stressDurationMinutes)
                : (DateTime?)null;
        }

        /// <summary>Checked on every tick in UpdateStressTimers (see below, next to TxtCpuStressTimer) — stops ALL active stress
        /// tests when the chosen duration is reached. A single shared deadline (not one per test type): if CPU Stress starts at
        /// minute 0 and Max Load at minute 2 with the same chosen duration, both stop together at the initial deadline — simple
        /// and predictable behaviour, not a small state machine per test.</summary>
        private void CheckStressAutoStop()
        {
            if (_stressAutoStopAtUtc == null) return;
            if (DateTime.UtcNow < _stressAutoStopAtUtc.Value) return;
            bool anyWasRunning = _cpuStress.Running || _gpuStress.IsRunning || _psuStress.IsRunning;
            if (!anyWasRunning) { _stressAutoStopAtUtc = null; return; }

            int minutesRan = _stressDurationMinutes;
            _stressAutoStopAtUtc = null;   // before stopping: a second tick does not re-enter here
            AppLogger.Info("Stress: automatic stop after {Min} min (Stop after)", minutesRan);
            try { StopCpuStress(); } catch (Exception ex) { AppLogger.Warning(ex, "AutoStop CPU"); }
            try { StopGpuStress(); } catch (Exception ex) { AppLogger.Warning(ex, "AutoStop GPU"); }
            try { StopAllStress(); } catch (Exception ex) { AppLogger.Warning(ex, "AutoStop all"); }   // stop only

            int cpuErr = SMDWin.Services.CpuStressor.IntegrityErrorCount;
            int gpuErr = SMDWin.Services.GpuStressService.IntegrityErrorCount;
            int ramErr = SMDWin.Services.PsuStressService.IntegrityErrorCount;
            int totalErr = cpuErr + gpuErr + ramErr;
            ShowToast(totalErr == 0
                ? string.Format(LanguageService.S("Msg", "StressDoneOkFmt"), minutesRan)
                : string.Format(LanguageService.S("Msg", "StressDoneErrFmt"), minutesRan, totalErr),
                totalErr == 0 ? "✓" : "⚠", 5000, totalErr == 0 ? ToastKind.Info : ToastKind.Warning);
            Fx.Done(this, totalErr == 0 ? PT("Stress test finished — no errors")
                                        : PT("Stress test finished — {0} errors", totalErr), problems: totalErr > 0);
        }

        private void OnSystemPowerModeChanged(object? sender, Microsoft.Win32.PowerModeChangedEventArgs e)
        {
            // power plugged in / unplugged: "Slower on battery" changes the read rate
            if (e.Mode == Microsoft.Win32.PowerModes.StatusChange) { _ = Dispatcher.BeginInvoke(new Action(ApplyUpdateSpeed)); return; }
            if (e.Mode != Microsoft.Win32.PowerModes.Suspend && e.Mode != Microsoft.Win32.PowerModes.Resume) return;
            bool suspend = e.Mode == Microsoft.Win32.PowerModes.Suspend;
            // The event comes on another thread; the stop goes through the UI (the same handlers as the buttons).
            _ = Dispatcher.BeginInvoke(new Action(() => StopStressAfterPowerEvent(suspend)));
            if (!suspend) _ = Dispatcher.BeginInvoke(new Action(OnResumeFromSleep));
        }

        private void StopStressAfterPowerEvent(bool suspend)
        {
            try
            {
                bool cpu = _cpuStress.Running, gpu = _gpuStress.IsRunning, psu = _psuStress.IsRunning;
                if (!cpu && !gpu && !psu) return;
                AppLogger.Info("Stress: stopped automatically — the system {Mode} (CPU={Cpu}, GPU={Gpu}, Max Load={Psu})",
                    suspend ? "is going to sleep/hibernation" : "returned from sleep/hibernation", cpu, gpu, psu);
                if (cpu) StopCpuStress();
                if (gpu) StopGpuStress();
                StopAllStress();   // also stops RAM+Disk; cannot start anything
                _stressAutoStopAtUtc = null;
                if (!suspend)
                    ShowToast(_LS("Stress", "StoppedBySleep"), "⏸", 7000, ToastKind.Warning);
            }
            catch (Exception ex) { AppLogger.Warning(ex, "StopStressAfterPowerEvent"); }
        }

        /// <summary>Sleep/resume: on return, the network cards may reconnect with a different state (Wi-Fi/Ethernet), and the
        /// remembered traffic values have a time gap of minutes/hours — force a refresh of the list and of the traffic sample,
        /// so a "0 KB/s" computed over a falsely long interval is not shown even briefly.</summary>
        private DateTime _lastResumeUtc = DateTime.MinValue;

        private void OnResumeFromSleep()
        {
            _lastResumeUtc = DateTime.UtcNow;
            try { SMDWin.Services.NetworkTrafficSampler.InvalidateAdapterCache(); }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
            AppLogger.Info("RESUME: the system returned from sleep/hibernation — network cache invalidated.");
            // the power chart on Power: a new point right after resume (otherwise it stays "frozen" until the next tick)
            if (_batTimer.IsEnabled)
                _ = Dispatcher.InvokeAsync(async () => { await System.Threading.Tasks.Task.Delay(2500); OnBatTick(null, EventArgs.Empty); });
        }


        internal void OpenAppLog_Click(object s, RoutedEventArgs e)
        {
            try
            {
                string dir = AppLogger.LogDirectory;
                Directory.CreateDirectory(dir);
                var latest = new DirectoryInfo(dir).GetFiles("smdwin-*.log")
                                 .OrderByDescending(f => f.LastWriteTimeUtc).FirstOrDefault();
                if (latest == null)
                {
                    // No file yet — open the folder.
                    System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(dir) { UseShellExecute = true });
                    return;
                }
                System.Diagnostics.Process.Start("explorer.exe", $"/select,\"{latest.FullName}\"");
            }
            catch (Exception ex) { AppDialog.Show(string.Format(LanguageService.S("Msg", "LogOpenFailFmt"), ex.Message), "SMD Win", AppDialog.Kind.Error); }
        }


