        /// <summary>PAWNIO: updates the state indicator (LED + text) in Settings.</summary>
        /// <summary>
        /// True when the processor temperature comes from a real sensor (the driver / sensor library), not from the
        /// approximate Windows zone. Null while it is too early to say (the first 30 s after start).
        /// </summary>
        private bool? CpuSensorsAnswer()
        {
            var sn = _lastTempSnap;
            if (sn?.CpuTemp is float && !(sn.CpuSensorName ?? "").StartsWith("ThermalZone", StringComparison.Ordinal)) return true;
            return _appStartStopwatch.Elapsed.TotalSeconds < 30 ? null : false;
        }

        private void RefreshPawnIoStatus()
        {
            try
            {
                bool installed = SMDWin.Services.PawnIOService.IsInstalled();
                bool isAdmin   = Environment.IsPrivilegedProcess;
                // installed, but no processor temperature comes from it: said plainly instead of "active"
                bool noData = installed && CpuSensorsAnswer() == false;

                // Settings card LED
                if (PawnIoLed != null)
                    PawnIoLed.Fill = (System.Windows.Media.Brush)FindResource(
                        installed && !noData ? "StatusOkBrush" : "StatusWarnBrush");
                if (TxtPawnIoStatus != null)
                    TxtPawnIoStatus.Text = noData ? _LS("PawnIo", "InstalledNoData")
                        : installed ? _LS("PawnIo", "Installed")
                        : _LS("PawnIo", "NotInstalled");
                if (BtnInstallPawnIo != null)
                    BtnInstallPawnIo.Visibility = installed ? Visibility.Collapsed : Visibility.Visible;

                // Sidebar tooltip LED (SidebarPawnIoLed + TxtSidebarPawnIo): PawnIO indicator shown in the tooltip of the sidebar admin bar
                if (FindName("SidebarPawnIoLed") is System.Windows.Shapes.Ellipse sLed)
                    sLed.Fill = (System.Windows.Media.Brush)FindResource(
                        installed && !noData ? "StatusOkBrush" : isAdmin ? "StatusWarnBrush" : "StatusErrorBrush");
                if (FindName("TxtSidebarPawnIo") is System.Windows.Controls.TextBlock sTxt)
                {
                    if (noData)
                        sTxt.Text = LanguageService.S("PawnIo", "StatusNoData");
                    else if (installed)
                        sTxt.Text = LanguageService.S("PawnIo", "StatusActive");
                    else if (!isAdmin)
                        sTxt.Text = LanguageService.S("PawnIo", "StatusUnavailable");
                    else
                        sTxt.Text = LanguageService.S("PawnIo", "StatusNotInstalled");
                }

                if (PawnIoMissingBanner != null)
                    PawnIoMissingBanner.Visibility = installed ? Visibility.Collapsed : Visibility.Visible;
                if (TxtPawnIoMissingBanner != null)
                    TxtPawnIoMissingBanner.Text = _LS("PawnIo", "SensorsUnavailableRetry");
            }
            catch (Exception ex) { AppLogger.Warning(ex, "RefreshPawnIoStatus"); }
        }

        private async void PawnIoMissingBanner_Click(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            try
            {
                if (SMDWin.Services.PawnIOService.IsInstalled()) { RefreshPawnIoStatus(); return; }
                await OfferPawnIOInstallAsync();
                RefreshPawnIoStatus();
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "PawnIoMissingBanner_Click");
                RefreshPawnIoStatus();
            }
        }


        internal void BtnInstallPawnIo_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                if (SMDWin.Services.PawnIOService.IsInstalled())
                {
                    RefreshPawnIoStatus();
                    return;
                }
                _ = ShowSensorSetupAsync();
            }
            catch (System.ComponentModel.Win32Exception) { RefreshPawnIoStatus(); }
            catch (Exception ex) { AppLogger.Warning(ex, "BtnInstallPawnIo_Click"); RefreshPawnIoStatus(); }
        }

        /// <summary>PAWNIO: offers to install the PawnIO driver if it is not present (the welcome window).</summary>
        private async Task OfferPawnIOInstallAsync()
        {
            try
            {
                if (SMDWin.Services.PawnIOService.IsInstalled()) return;
                await ShowSensorSetupAsync();
            }
            catch (Exception ex) { AppLogger.Warning(ex, "OfferPawnIOInstallAsync"); }
        }

        private SensorSetupWindow? _sensorSetupWin;

        /// <summary>
        /// The welcome window for the sensor driver: it asks, installs (Windows asks for permission), then starts the sensors.
        /// Used at the first start and by the "Install" button in Settings / the title-bar banner. Returns true when installed.
        /// It is NOT modal: a modal window opened during start-up holds every start-up step queued under it (the dashboard and
        /// the sensors waited minutes for an answer), so the app keeps loading behind it.
        /// </summary>
        private Task<bool> ShowSensorSetupAsync()
        {
            if (_sensorSetupWin != null)
            {
                _sensorSetupWin.Activate();
                return Task.FromResult(false);
            }
            var done = new TaskCompletionSource<bool>();
            var win = new SensorSetupWindow(async progress =>
            {
                ToolActivityLog.Add("PawnIO", "Install driver (user clicked Install)", "info");
                bool ok = await SMDWin.Services.PawnIOService.InstallAsync(progress);
                if (!ok) return false;
                progress.Report(LanguageService.S("SensorSetup", "Activating", "Starting the sensors…"));
                await InitLhmWithRetryAsync();
                // "sensors active" only when a processor temperature really arrives (up to ~10 s after the start)
                bool answer = false;
                for (int i = 0; i < 20 && !answer; i++)
                {
                    await Task.Delay(500);
                    var sn = _lastTempSnap;
                    answer = sn?.CpuTemp is float && !(sn.CpuSensorName ?? "").StartsWith("ThermalZone", StringComparison.Ordinal);
                }
                AppLogger.Info("PawnIO installed — processor temperature from the sensors after install: {0}", answer ? "yes" : "no");
                _sensorSetupWin?.SetSensorsAnswer(answer);
                RefreshPawnIoStatus();
                return true;
            });
            if (IsVisible) win.Owner = this;
            else win.WindowStartupLocation = WindowStartupLocation.CenterScreen;
            win.Closed += (_, _) =>
            {
                _sensorSetupWin = null;
                RefreshPawnIoStatus();
                done.TrySetResult(win.Installed);
            };
            _sensorSetupWin = win;
            win.Show();
            return done.Task;
        }

