        // Kept as an entry point (called when Settings loads) — now builds the matrix.
        private void LoadCompactMetricCheckboxes(string csv) => BuildMetricsMatrix();

        // ── The Widget / Tray metrics matrix ───────────────────────
        // One row per metric, a checkbox for Widget (WidgetCompactMetrics) and one for Tray
        // (TraySensorMetricsOverride, the same list as the icon menu).
        private const int TrayIconLimit = 8;
        private bool _buildingMetricsMatrix;
        // „pastile” (ToggleButton)
        private readonly List<System.Windows.Controls.Primitives.ToggleButton> _mmWidget = new();
        private readonly List<System.Windows.Controls.Primitives.ToggleButton> _mmTray   = new();

        /// <summary>Metrics that make sense as a tray icon (no CPU frequency / battery time — they do not fit legibly on 16 px
        /// and are not values to watch from the corner of the screen).</summary>
        private static readonly string[] TrayChipMetrics =
            { "CPUTemp", "CPU", "GPUTemp", "GPU", "RAM", "Battery", "NetDown", "NetUp", "DiskRead", "DiskWrite" };

        private static bool SystemHasBattery()
        {
            try { return !Forms.SystemInformation.PowerStatus.BatteryChargeStatus.HasFlag(Forms.BatteryChargeStatus.NoSystemBattery); }
            catch (Exception ex) { AppLogger.Debug($"SystemHasBattery: {ex.Message}"); return true; }
        }

        /// <summary>The widget / tray options are visible only while their switch is on.</summary>
        private void UpdateWidgetTrayPanels()
        {
            try
            {
                if (PnlCompactMetrics != null)
                    PnlCompactMetrics.Visibility = ChkWidgetEnabled?.IsChecked == true ? Visibility.Visible : Visibility.Collapsed;
                if (FindName("PnlTrayOptions") is FrameworkElement tray)
                    tray.Visibility = SettingsService.Current.TraySensorsEnabled ? Visibility.Visible : Visibility.Collapsed;
            }
            catch (Exception ex) { AppLogger.Debug($"UpdateWidgetTrayPanels: {ex.Message}"); }
        }

        /// <summary>A checkbox (the 3-column list in Settings › Widget and tray); disabled = dimmed.</summary>
        private System.Windows.Controls.Primitives.ToggleButton MakeMetricChip(string text, string metric, bool on)
        {
            var cb = new System.Windows.Controls.CheckBox
            {
                Content = text, Tag = metric, IsChecked = on, Margin = new Thickness(0, 0, 12, 8),
                Style = TryFindResource("VanillaCheckBoxStyle") as Style,
            };
            cb.IsEnabledChanged += (_, _) => cb.Opacity = cb.IsEnabled ? 1.0 : 0.45;
            return cb;
        }


        /// <summary>The full name, for the pill tooltip.</summary>
        private static string LiveMetricFullName(string metric, bool ro) => metric switch
        {
            "CPUTemp"     => ro ? "Temperatură CPU"      : "CPU temperature",
            "CPU"         => ro ? "Încărcare CPU"        : "CPU load",
            "CPUFreq"     => ro ? "Frecvență CPU"        : "CPU frequency",
            "GPUTemp"     => ro ? "Temperatură GPU"      : "GPU temperature",
            "GPU"         => ro ? "Încărcare GPU"        : "GPU load",
            "RAM"         => ro ? "Memorie RAM folosită" : "RAM usage",
            "Battery"     => ro ? "Nivel baterie"        : "Battery level",
            "BatteryTime" => ro ? "Timp rămas baterie"   : "Battery time left",
            "NetDown"     => ro ? "Viteză download"      : "Download speed",
            "NetUp"       => ro ? "Viteză upload"        : "Upload speed",
            "DiskRead"    => ro ? "Citire disc"          : "Disk read",
            "DiskWrite"   => ro ? "Scriere disc"         : "Disk write",
            _             => metric,
        };

        private void BuildMetricsMatrix()
        {
            if (FindName("WidgetMetricChips") is not System.Windows.Controls.Panel wChips
                || FindName("TrayMetricChips") is not System.Windows.Controls.Panel tChips) return;
            _buildingMetricsMatrix = true;
            try
            {
                bool ro = LanguageService.CurrentCode == "ro";
                bool hasBattery = SystemHasBattery();
                wChips.Children.Clear(); tChips.Children.Clear();
                _mmWidget.Clear(); _mmTray.Clear();

                var widgetSet = (SettingsService.Current.WidgetCompactMetrics ?? "")
                                .Split(',', StringSplitOptions.RemoveEmptyEntries).ToHashSet();
                var traySet   = GetActiveTraySensorMetrics().ToHashSet();

                foreach (var metric in AllLiveMetrics)
                {
                    // Battery (level / time left) only on systems with a battery — but keep the checkbox if it was already active
                    // (e.g. settings brought from a laptop), so it can be removed.
                    bool isBat = metric is "Battery" or "BatteryTime";
                    if (isBat && !hasBattery && !widgetSet.Contains(metric)) { }
                    else
                    {
                        var chip = MakeMetricChip(LiveMetricFullName(metric, ro), metric, widgetSet.Contains(metric));
                        chip.ToolTip = LiveMetricFullName(metric, ro);
                        chip.Click += (_, _) => OnMetricsMatrixChanged();
                        wChips.Children.Add(chip);
                        _mmWidget.Add(chip);
                    }

                    if (Array.IndexOf(TrayChipMetrics, metric) < 0) continue;
                    if (isBat && !hasBattery && !traySet.Contains(metric)) continue;
                    var tchip = MakeMetricChip(LiveMetricFullName(metric, ro), metric, traySet.Contains(metric));
                    tchip.Click += (_, _) => OnMetricsMatrixChanged();
                    tChips.Children.Add(tchip);
                    _mmTray.Add(tchip);
                }

                // Tray metrics set from the icon menu but without a pill (e.g. CPUFreq) — stay active, they just can no longer be added
                // from here; they are kept in the list on save (see OnMetricsMatrixChanged).
                _trayHiddenActive = traySet.Where(m => !_mmTray.Any(c => (string)c.Tag == m)).ToList();

                if (FindName("TxtTrayMetricsHint") is TextBlock hint)
                    hint.Text = ro ? $"Maximum {TrayIconLimit} iconițe · vitezele apar prescurtat pe iconiță (ex. 1.2M), complet în tooltip"
                                   : $"Up to {TrayIconLimit} icons · speeds are shortened on the icon (e.g. 1.2M), full value in the tooltip";

                ApplyTrayIconLimit();
                UpdateWidgetTrayPanels();
            }
            catch (Exception ex) { AppLogger.Debug($"BuildMetricsMatrix: {ex.Message}"); }
            finally { _buildingMetricsMatrix = false; }
        }

        private List<string> _trayHiddenActive = new();

        /// <summary>With 8 icons checked in the tray, the remaining Tray checkboxes are disabled.</summary>
        private void ApplyTrayIconLimit()
        {
            int n = _mmTray.Count(c => c.IsChecked == true) + _trayHiddenActive.Count;
            bool ro = LanguageService.CurrentCode == "ro";
            foreach (var c in _mmTray)
            {
                bool blocked = n >= TrayIconLimit && c.IsChecked != true;
                c.IsEnabled = !blocked;
                c.ToolTip = blocked ? (ro ? $"Maximum {TrayIconLimit} iconițe în tray" : $"Up to {TrayIconLimit} tray icons")
                                    : LiveMetricFullName((string)c.Tag, ro);
            }
        }

        private void OnMetricsMatrixChanged()
        {
            if (_buildingMetricsMatrix) return;
            string widgetCsv = string.Join(",", _mmWidget.Where(c => c.IsChecked == true).Select(c => (string)c.Tag));
            string trayCsv   = string.Join(",", _mmTray.Where(c => c.IsChecked == true).Select(c => (string)c.Tag)
                                                   .Concat(_trayHiddenActive));
            SettingsService.Current.WidgetCompactMetrics      = widgetCsv;
            SettingsService.Current.TraySensorMetricsOverride = trayCsv;
            SettingsService.Save();
            ApplyTrayIconLimit();

            try { _compactWidget?.ApplyMetrics(); }
            catch (Exception ex) { AppLogger.Debug($"MetricsMatrix widget refresh: {ex.Message}"); }
            try { RebuildTraySensorIcons(); }
            catch (Exception ex) { AppLogger.Debug($"MetricsMatrix tray refresh: {ex.Message}"); }
        }

