        /// <summary>The °C / °F symbol next to the digits in XAML (DynamicResource TempUnitSymbol).</summary>
        private static void ApplyTempUnit()
        {
            if (Application.Current != null) Application.Current.Resources["TempUnitSymbol"] = TempUnit.Symbol;
