        /// <summary>Small screen (13–14" laptop, or large scaling in Windows) → compact interface.</summary>
        private static bool ScreenWantsCompact()
        {
            var wa = SystemParameters.WorkArea;   // in WPF units, so it takes the Windows scaling into account
            return wa.Height < 860 || wa.Width < 1440;
        }

        /// <summary>Compact = the whole window scaled to 90%, to fit more on small screens.</summary>
        private void ApplyUiDensity()
        {
            try
            {
                string pref = SettingsService.Current.UiDensity ?? "Auto";
                bool compact = pref == "Compact" || (pref != "Normal" && ScreenWantsCompact());
                if (RootGrid != null)
                    RootGrid.LayoutTransform = compact ? new ScaleTransform(0.9, 0.9) : Transform.Identity;
                UpdateDensityDescription();
                SetTileActive(BtnDensityAuto, pref != "Compact" && pref != "Normal");
                SetTileActive(BtnDensityCompact, pref == "Compact");
                SetTileActive(BtnDensityNormal, pref == "Normal");
                CheckSilently(pref == "Compact" ? "RbDensityCompact" : pref == "Normal" ? "RbDensityNormal" : "RbDensityAuto");
            }
            catch (Exception ex) { AppLogger.Warning(ex, "ApplyUiDensity"); }
        }

        /// <summary>The small line under "Interface density": what Auto chose on this screen — short, in the app language.</summary>
        private void UpdateDensityDescription()
        {
            if (TxtDensityDesc == null) return;
            string pref = SettingsService.Current.UiDensity ?? "Auto";
            bool auto = pref != "Compact" && pref != "Normal";
            TxtDensityDesc.Text = !auto ? LanguageService.S("Settings", "DensityAutoHint", "Auto picks it by screen size")
                : ScreenWantsCompact() ? LanguageService.S("Settings", "DensityAutoCompact", "Auto · compact here")
                                       : LanguageService.S("Settings", "DensityAutoNormal", "Auto · normal here");
        }

        private void LoadBehaviorPrefsIntoUI()
        {
            var s = SettingsService.Current;
            if (RbTempUnitF != null) RbTempUnitF.IsChecked = TempUnit.Fahrenheit;
            if (RbTempUnitC != null) RbTempUnitC.IsChecked = !TempUnit.Fahrenheit;
            if (TxtWorkshopName != null && TxtWorkshopName.Text != (s.WorkshopName ?? "")) TxtWorkshopName.Text = s.WorkshopName ?? "";
            _savedWorkshopName = s.WorkshopName ?? "";
            LoadBgRecIntoUI();
            ApplyUiDensity();
        }

        internal void TempUnitChip_Checked(object sender, RoutedEventArgs e)
        {
            if (!IsLoaded || sender is not System.Windows.Controls.RadioButton rb) return;
            string unit = rb.Tag?.ToString() == "F" ? "F" : "C";
            if (SettingsService.Current.TemperatureUnit == unit) return;
            SettingsService.Current.TemperatureUnit = unit;
            ApplyTempUnit();
            try { SettingsService.Save(); } catch (Exception ex) { AppLogger.Warning(ex, "TempUnitChip_Checked"); }
        }

        internal void DensityPreview_Click(object sender, RoutedEventArgs e)
        {
            if (sender is not FrameworkElement fe) return;
            string pref = fe.Tag?.ToString() ?? "Auto";
            if (SettingsService.Current.UiDensity == pref) return;
            SettingsService.Current.UiDensity = pref;
            ApplyUiDensity();
            try { SettingsService.Save(); } catch (Exception ex) { AppLogger.Warning(ex, "DensityChip_Checked"); }
        }

        internal void TxtWorkshopName_TextChanged(object sender, TextChangedEventArgs e)
        {
            if (TxtWorkshopName != null) SettingsService.Current.WorkshopName = TxtWorkshopName.Text.Trim();
        }

        private string _savedWorkshopName = "";

        internal void TxtWorkshopName_LostFocus(object sender, RoutedEventArgs e) => SaveWorkshopName();

        internal void TxtWorkshopName_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
        {
            if (e.Key == System.Windows.Input.Key.Enter) { SaveWorkshopName(); e.Handled = true; }
        }

        /// <summary>Saves the name and confirms visibly where it will appear (otherwise the field seems to do nothing).</summary>
        private void SaveWorkshopName()
        {
            try
            {
                string name = SettingsService.Current.WorkshopName ?? "";
                if (name == _savedWorkshopName) return;
                _savedWorkshopName = name;
                SettingsService.Save();
                if (FindName("TxtWorkshopSaved") is TextBlock t)
                    t.Text = name.Length > 0
                        ? string.Format(LanguageService.S("Settings", "WorkshopSavedNamed", "Saved — reports will show „{0}”"), name)
                        : LanguageService.S("Settings", "WorkshopSavedEmpty", "Saved — reports without a workshop name");
            }
            catch (Exception ex) { AppLogger.Warning(ex, "SaveWorkshopName"); }
        }
    }
}
